Cho hình vẽ sau. Trong các khẳng định sau khẳng định nào sai?

\choice
{ \True  $FH$ là tia phân giác của $\widehat{ EFN}$ }
   { $\widehat{HFN }= 44^{\circ}$  }
     { $EM//GH$  }
    {  $\widehat{HFN }= 41^{\circ}$ }
}{
\begin{tikzpicture}
            \coordinate (E) at (4, 3);
            \coordinate (D) at (3, 2);
            \coordinate (C) at (-6, 2);
            \coordinate (B) at (-2, 2);
            \coordinate (A) at (-1, 3);
            \coordinate (F) at (0, 0);

            % Vẽ tứ giác
            \draw[thick] (C) -- (B)--(D);
            \draw[thick] (A) -- (E);
            \draw[thick] (A) -- (B);
            \draw[thick] (B) --(F);
            % Ghi nhãn các điểm

            \node[above] at (A) {$E$};
            \node[above ] at (B){$F$};
                      \node[above] at (C) {$G$};
                        \node[above] at (D) {$H$};
                         \node[above] at (E) {$M$};
                        \node[above] at (F) {$N$};

    \draw 
            (A) pic[draw,angle radius = 10] {angle = B--A--E} node[shift={(-20:20pt)}]{$ 139^\circ $}   
            ;    
            \draw 
            (B) pic[draw,angle radius = 10] {angle = F--B--A} pic[draw,angle radius = 12] {angle = F--B--A} node[shift={(-5:25pt)}]{$ 85^\circ $}   
            ;    
            \draw 
            (B) pic[draw,angle radius = 10] {angle = C--B--F}  pic[draw,angle radius = 8] {angle = C--B--F}  pic[draw,angle radius = 12] {angle = C--B--F} node[shift={(20:-20pt)}]{$ 136^\circ $}   
            ;  
        \end{tikzpicture}
}
\loigiai{
$\widehat{HFN }= 44^{\circ}$ suy ra $\widehat{EFH }= \widehat{EFN}- \widehat{HFN }=41^{\circ}$\\
Ta có $\widehat{EFH }+\widehat{FEM } =180^{\circ}$ mà 2 góc ở vị trí trong cùng phía nên suy ra $EM//GH$.\\
Vì  $\widehat{EFH }\ne \widehat{HFN }$ nên $FH$ không là tia phân giác của $\widehat{ EFN}$
}\end{ex}

