Cho hình vẽ sau. Trong các khẳng định sau khẳng định nào sai?

\choice
{ \True  $KF$ là tia phân giác của $\widehat{ QKI}$ }
   { $QE//HF$  }
     {  $\widehat{FKI }= 54^{\circ}$ }
    { $\widehat{FKI }= 46^{\circ}$  }
}{
\begin{tikzpicture}
            \coordinate (E) at (4, 3);
            \coordinate (D) at (3, 2);
            \coordinate (C) at (-6, 2);
            \coordinate (B) at (-2, 2);
            \coordinate (A) at (-1, 3);
            \coordinate (F) at (0, 0);

            % Vẽ tứ giác
            \draw[thick] (C) -- (B)--(D);
            \draw[thick] (A) -- (E);
            \draw[thick] (A) -- (B);
            \draw[thick] (B) --(F);
            % Ghi nhãn các điểm

            \node[above] at (A) {$Q$};
            \node[above ] at (B){$K$};
                      \node[above] at (C) {$H$};
                        \node[above] at (D) {$F$};
                         \node[above] at (E) {$E$};
                        \node[above] at (F) {$I$};

    \draw 
            (A) pic[draw,angle radius = 10] {angle = B--A--E} node[shift={(-20:20pt)}]{$ 126^\circ $}   
            ;    
            \draw 
            (B) pic[draw,angle radius = 10] {angle = F--B--A} pic[draw,angle radius = 12] {angle = F--B--A} node[shift={(-5:25pt)}]{$ 100^\circ $}   
            ;    
            \draw 
            (B) pic[draw,angle radius = 10] {angle = C--B--F}  pic[draw,angle radius = 8] {angle = C--B--F}  pic[draw,angle radius = 12] {angle = C--B--F} node[shift={(20:-20pt)}]{$ 134^\circ $}   
            ;  
        \end{tikzpicture}
}
\loigiai{
$\widehat{FKI }= 46^{\circ}$ suy ra $\widehat{QKF }= \widehat{QKI}- \widehat{FKI }=54^{\circ}$\\
Ta có $\widehat{QKF }+\widehat{KQE } =180^{\circ}$ mà 2 góc ở vị trí trong cùng phía nên suy ra $QE//HF$.\\
Vì  $\widehat{QKF }\ne \widehat{FKI }$ nên $KF$ không là tia phân giác của $\widehat{ QKI}$
}\end{ex}

